reference_solution:
def count_digit_one(n):
    total, place = 0, 1
    while place <= n:
        lower = n % place
        digit = (n // place) % 10
        higher = n // (place * 10)
        if digit == 0:
            total += higher * place
        elif digit == 1:
            total += higher * place + lower + 1
        else:
            total += (higher + 1) * place
        place *= 10
    return total

